/* @lc app=leetcode id=2402 lang=kotlin */ class Solution { fun mostBooked(n: Int, meetings: Array<IntArray>): Int = java.util.PriorityQueue<Int>().also { f -> (0 until n).forEach { f.add(it) } }.let { free -> java.util.PriorityQueue<LongArray>(compareBy<LongArray>({ it[0] }, { it[1] })).let { busy -> IntArray(n).also { cnt -> meetings.sortedBy { it[0] }.forEach { (s, e, _) -> generateSequence { busy.peek()?.takeIf { it[0] <= s } }.forEach { _ -> free.add(busy.poll()[1].toInt()) }.let { (if (free.isEmpty()) busy.poll().let { b -> b[1].toInt() to b[0] } else free.poll() to s.toLong()).let { (room, st) -> busy.add(longArrayOf(st + e - s, room.toLong())).also { cnt[room]++ } } } } }.let { cnt -> cnt.indices.maxBy { cnt[it] } } } } }